import axios from "axios";
import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
const baseUrl='http://127.0.0.1:8000/api'
function Teacherlogin() {
    const[teacherLoginData,setteacherLoginData]=useState({
        email:'',
        password:''
    })
    const handleChange=(event)=>{
        setteacherLoginData({
            ...teacherLoginData,
            [event.target.name]:event.target.value
        })
    }
    const submitForm=()=>{
        const teacherFormData=new FormData;
        teacherFormData.append('email',teacherLoginData.email)
        teacherFormData.append('password',teacherLoginData.password)
        try{
        axios.post(baseUrl+'/teacher-login',teacherFormData).then((res)=>{
            if(res.data.bool==true){
                localStorage.setItem('teacherLoginStatus')
            }
        });
    }
        catch(error){
           console.log(error) 
        }
    }
    useEffect(()=>{
        document.title="Teacher Login"
    })
  return (
      <div className="container mt-4">
        <div className="row">
            <div className="col-6 offset-3">
                <div className="card">
                    <h5 className="card-header">Teacher Login</h5>
                    <div className="card-body">
                        <form>
                            <div className="mb-3">
                                <label htmlFor="email" className="form-label">Email</label>
                                <input type="email" name="email" onChange={handleChange} value={teacherLoginData.email} className="form-control"/>
                            </div>
                            <div className="mb-3">
                                <label htmlFor="password" className="form-label">Password</label>
                                <input type="password" name="password" onChange={handleChange} value={teacherLoginData.password} className="form-control" id="password"/>
                            </div>
                        
                            <button type="submit" className="btn btn-primary" onClick={submitForm}>Login</button>
                        </form>
                    </div>
                </div>
            </div>
        </div>
      </div>
  )
}

export default Teacherlogin;
